#!/usr/bin/env node
/**
 * gen-support-matrix — generate docs/SUPPORT-MATRIX.md: every published package, its internal
 * consumers (AgentsKit-io and NoxCodeSolutions, read from package.json files), version and
 * status (supported or community/experimental), plus the 1.0 criteria for supported packages.
 *
 *   node scripts/gen-support-matrix.mjs             # rewrite docs/SUPPORT-MATRIX.md and the README block
 *   node scripts/gen-support-matrix.mjs --check     # fail when the generated files drift
 *   node scripts/gen-support-matrix.mjs --apply     # also sync the "experimental" npm keyword
 *   node scripts/gen-support-matrix.mjs --refresh   # re-read consumer manifests through `gh api` first
 *
 * A package is supported when an internal consumer depends on it: a workspace app in this
 * repository or a repository listed in docs/support-consumers.json. Packages with no consumer are
 * experimental; that label never blocks a release. A supported package meets the 1.0 criteria with
 * a consumer in production or homolog, green CI on the default branch, no breaking change in the
 * last four changelog versions, and docs (README plus reference page).
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

export const EXPERIMENTAL_KEYWORD = 'experimental'
export const README_START = '<!-- support-matrix:start -->'
export const README_END = '<!-- support-matrix:end -->'
const LIVE_ENVIRONMENTS = new Set(['production', 'homolog'])
const DEP_FIELDS = ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']

/** Names of `@agentskit/*` packages a package.json object depends on. */
export function agentskitDependencies(manifest) {
  const names = new Set()
  for (const field of DEP_FIELDS) {
    for (const name of Object.keys(manifest[field] ?? {})) {
      if (name.startsWith('@agentskit/')) names.add(name)
    }
  }
  return [...names].sort()
}

/** True when any of the last `limit` changelog versions mentions a breaking change. */
export function hasRecentBreakingChange(changelog, limit = 4) {
  const sections = changelog.split(/^## /m).slice(1, limit + 1)
  return sections.some((section) => /\bBREAKING\b|^#+\s*Major Changes|^\S[^\n]*!:/im.test(section))
}

/** Builds the matrix rows from package manifests and consumer data. */
export function buildRows({ packages, consumers, ci }) {
  return packages
    .map((pkg) => {
      const users = consumers.filter((c) => c.dependencies.includes(pkg.name))
      const supported = users.length > 0
      const live = users.some((c) => LIVE_ENVIRONMENTS.has(c.environment))
      const criteria = {
        consumer: live,
        ci: ci === 'green',
        noBreaking: !pkg.breaking,
        docs: pkg.docs,
      }
      const alreadyStable = Number(pkg.version.split('.')[0]) >= 1
      return {
        name: pkg.name,
        version: pkg.version,
        consumers: users.map((c) => c.repo),
        supported,
        criteria,
        eligible: supported && !alreadyStable && Object.values(criteria).every(Boolean),
        stable: alreadyStable,
      }
    })
    .sort((a, b) => a.name.localeCompare(b.name))
}

const mark = (value) => (value ? '✅' : '❌')

/** Renders docs/SUPPORT-MATRIX.md. */
export function renderMatrix(rows, ci) {
  const lines = [
    '# Support matrix',
    '',
    '> Generated by `node scripts/gen-support-matrix.mjs` — do not edit by hand.',
    '',
    'A package is **supported** when an internal consumer (AgentsKit-io or NoxCodeSolutions; workspace apps count as `apps/*`) depends on it in its `package.json`.',
    'Packages without a consumer are **experimental** (community-maintained): they carry the `experimental` npm keyword and never block a release.',
    '',
    'A supported package is **eligible for 1.0** when it has a consumer in production or homolog, green CI on the default branch,',
    'no breaking change in its last four versions, and docs. Eligible packages are promoted in one batch PR the owner approves.',
    '',
    `CI on the default branch: **${ci}**.`,
    '',
    '> **Known limitation:** NoxCodeSolutions repositories are not read yet. The factory token cannot access them, so packages used only there show as experimental until their manifests are added to `docs/support-consumers.json` (follow-up: consumer repositories of NoxCodeSolutions).',
    '',
    '| Package | Version | Status | Internal consumers | Consumer live | CI green | No breaking (4 versions) | Docs | 1.0 |',
    '| --- | --- | --- | --- | --- | --- | --- | --- | --- |',
  ]
  for (const row of rows) {
    const status = row.supported ? 'supported' : 'experimental'
    const consumers = row.consumers.length ? row.consumers.join(', ') : '—'
    const cells = row.supported
      ? [...Object.values(row.criteria).map(mark), oneZeroCell(row)]
      : ['—', '—', '—', '—', '—']
    lines.push(`| \`${row.name}\` | ${row.version} | ${status} | ${consumers} | ${cells.join(' | ')} |`)
  }
  return `${lines.join('\n')}\n`
}

function oneZeroCell(row) {
  if (row.stable) return '1.x'
  return row.eligible ? '✅ eligible' : 'not yet'
}

/** Renders the README block listing experimental packages. */
export function renderReadmeBlock(rows) {
  const experimental = rows.filter((row) => !row.supported)
  const body = experimental.length
    ? experimental.map((row) => `- \`${row.name}\``).join('\n')
    : '- none'
  return [
    README_START,
    '**Experimental packages** (no internal consumer yet; community-maintained, tagged `experimental` on npm, never blocking a release). See the [support matrix](./docs/SUPPORT-MATRIX.md).',
    '',
    body,
    README_END,
  ].join('\n')
}

/** Replaces the block between the README markers, or inserts it before `anchor`. */
export function updateReadme(readme, block, anchor = '## Verified proof') {
  const start = readme.indexOf(README_START)
  const end = readme.indexOf(README_END)
  if (start !== -1 && end > start) return readme.slice(0, start) + block + readme.slice(end + README_END.length)
  const at = readme.indexOf(anchor)
  if (at === -1) throw new Error(`README anchor "${anchor}" not found`)
  return `${readme.slice(0, at)}${block}\n\n${readme.slice(at)}`
}

/** Adds or removes the experimental keyword; returns the new keywords. */
export function syncKeyword(keywords, experimental) {
  const rest = (keywords ?? []).filter((k) => k !== EXPERIMENTAL_KEYWORD)
  return experimental ? [...rest, EXPERIMENTAL_KEYWORD] : rest
}

const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'))

function loadPackages(root) {
  const docsRoot = join(root, 'apps', 'docs-next', 'content', 'docs', 'reference', 'packages')
  const out = []
  for (const entry of readdirSync(join(root, 'packages'), { withFileTypes: true })) {
    if (!entry.isDirectory()) continue
    const dir = join(root, 'packages', entry.name)
    const manifestPath = join(dir, 'package.json')
    if (!existsSync(manifestPath)) continue
    const manifest = readJson(manifestPath)
    if (manifest.private || !manifest.name) continue
    const changelogPath = join(dir, 'CHANGELOG.md')
    out.push({
      name: manifest.name,
      version: manifest.version,
      manifestPath,
      manifest,
      breaking: existsSync(changelogPath) && hasRecentBreakingChange(readFileSync(changelogPath, 'utf8')),
      docs: existsSync(join(dir, 'README.md')) && existsSync(join(docsRoot, `${entry.name}.mdx`)),
    })
  }
  return out
}

/** Workspace apps are AgentsKit-io consumers read straight from their package.json. */
function loadWorkspaceConsumers(root) {
  const out = []
  const appsDir = join(root, 'apps')
  for (const entry of readdirSync(appsDir, { withFileTypes: true })) {
    const manifestPath = join(appsDir, entry.name, 'package.json')
    if (!entry.isDirectory() || !existsSync(manifestPath)) continue
    const dependencies = agentskitDependencies(readJson(manifestPath))
    // The docs and registry sites are what ships to users; examples are development only.
    const environment = ['landing', 'docs-next', 'registry', 'ask-backend'].includes(entry.name)
      ? 'production'
      : 'development'
    out.push({ repo: `apps/${entry.name}`, environment, dependencies })
  }
  return out
}

async function gh(args) {
  const { runCommand } = await import('../packages/cross-platform/dist/index.js')
  const result = await runCommand('gh', args)
  if (result.code !== 0) throw new Error(`gh ${args.join(' ')} failed: ${result.stderr}`)
  return JSON.parse(result.stdout)
}

async function refreshSnapshot(snapshot) {
  const consumers = []
  for (const consumer of snapshot.consumers) {
    const names = new Set()
    for (const path of consumer.manifests) {
      const file = await gh(['api', `repos/${consumer.repo}/contents/${path}`])
      const manifest = JSON.parse(Buffer.from(file.content, 'base64').toString('utf8'))
      for (const name of agentskitDependencies(manifest)) names.add(name)
    }
    consumers.push({ ...consumer, dependencies: [...names].sort() })
  }
  const [run] = await gh(['run', 'list', '--repo', 'AgentsKit-io/agentskit', '--branch', 'main', '--workflow', 'ci.yml', '--status', 'completed', '--limit', '1', '--json', 'conclusion'])
  return { ...snapshot, consumers, ci: { status: run?.conclusion === 'success' ? 'green' : 'red' } }
}

async function main() {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
  const args = new Set(process.argv.slice(2))
  const snapshotPath = join(root, 'docs', 'support-consumers.json')
  let snapshot = readJson(snapshotPath)
  if (args.has('--refresh')) {
    snapshot = await refreshSnapshot(snapshot)
    writeFileSync(snapshotPath, `${JSON.stringify(snapshot, null, 2)}\n`)
  }
  const packages = loadPackages(root)
  const consumers = [...loadWorkspaceConsumers(root), ...snapshot.consumers]
  const ci = snapshot.ci?.status ?? 'unknown'
  const rows = buildRows({ packages, consumers, ci })

  const matrixPath = join(root, 'docs', 'SUPPORT-MATRIX.md')
  const readmePath = join(root, 'README.md')
  const matrix = renderMatrix(rows, ci)
  const readme = updateReadme(readFileSync(readmePath, 'utf8'), renderReadmeBlock(rows))

  const keywordEdits = []
  for (const row of rows) {
    const pkg = packages.find((p) => p.name === row.name)
    const next = syncKeyword(pkg.manifest.keywords, !row.supported)
    if (JSON.stringify(next) !== JSON.stringify(pkg.manifest.keywords ?? [])) {
      keywordEdits.push({ pkg, next })
    }
  }

  if (args.has('--check')) {
    const stale = []
    if (!existsSync(matrixPath) || readFileSync(matrixPath, 'utf8') !== matrix) stale.push('docs/SUPPORT-MATRIX.md')
    if (readFileSync(readmePath, 'utf8') !== readme) stale.push('README.md')
    for (const { pkg } of keywordEdits) stale.push(`${pkg.name} keywords`)
    if (stale.length) {
      console.error(`Support matrix drift: ${stale.join(', ')}. Run node scripts/gen-support-matrix.mjs --apply`)
      process.exit(1)
    }
    return
  }
  writeFileSync(matrixPath, matrix)
  writeFileSync(readmePath, readme)
  if (args.has('--apply')) {
    for (const { pkg, next } of keywordEdits) {
      writeFileSync(pkg.manifestPath, `${JSON.stringify({ ...pkg.manifest, keywords: next }, null, 2)}\n`)
    }
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main()
